/// <summary>
/// uploadSample request: one confirmed AI count. ImageBase64 is a small JPEG.
/// </summary>
[DataContractAttribute]
class HSMobileOpsAiSampleRequest
{
    DataAreaId dataAreaId;
    str sampleId;
    str itemId;
    int quantity;
    int corrections;
    str annotation;
    str imageBase64;
    str deviceId;
    str userName;
    str warehouseId;

}

Method.Source:
[DataMemberAttribute('DataAreaId')]
public DataAreaId parmDataAreaId(DataAreaId _value = dataAreaId)
{
    dataAreaId = _value;
    return dataAreaId;
}

[DataMemberAttribute('SampleId')]
public str parmSampleId(str _value = sampleId)
{
    sampleId = _value;
    return sampleId;
}

